package com.kartgarden.live.protocol;

import static org.junit.Assert.*;

import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.*;
import org.json.*;
import org.junit.Test;

/** Oracle values are generated by the real Swift 122 recorder on original native packets. */
public class OrientationParityTest {
  private void replay(String version) throws Exception {
    Path input =
        Path.of(
            System.getProperty("kart.fixtureDir", "app/build/swift-fixtures"), version + ".csv");
    assertTrue("Run tools/fetch-swift-fixtures.py first", Files.isRegularFile(input));
    JSONObject manifest;
    JSONArray golden;
    try (var in = getClass().getResourceAsStream("/swift122/MANIFEST.json")) {
      assertNotNull(in);
      manifest = new JSONObject(new String(in.readAllBytes(), StandardCharsets.UTF_8));
    }
    try (var in = getClass().getResourceAsStream("/swift122/" + version + ".json")) {
      assertNotNull(in);
      golden = new JSONArray(new String(in.readAllBytes(), StandardCharsets.UTF_8));
    }
    String hash =
        HexFormat.of()
            .formatHex(MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(input)));
    assertEquals(
        manifest.getJSONObject("expectations").getJSONObject(version).getString("input_sha256"),
        hash);
    List<String> lines = Files.readAllLines(input);
    String[] columns = lines.get(0).split(",", -1);
    int time = Arrays.asList(columns).indexOf("elapsed_seconds"),
        hex = Arrays.asList(columns).indexOf("raw_packet_hex");
    double first = Double.parseDouble(lines.get(1).split(",", -1)[time]);
    Orientation orientation = new Orientation();
    boolean requested = false;
    int comparisons = 0, samples = 0;
    for (int packet = 1; packet < lines.size(); packet++) {
      String[] fields = lines.get(packet).split(",", -1);
      double seconds = Double.parseDouble(fields[time]);
      long now = Math.round(seconds * 1e9);
      if (!requested && seconds - first >= 3) {
        orientation.calibrate(now, true);
        requested = true;
      }
      Telemetry t = Telemetry.parse(HexFormat.of().parseHex(fields[hex]));
      assertTrue(t.valid);
      samples += t.samples.size();
      orientation.update(t, now);
      if (comparisons >= golden.length()
          || golden.getJSONObject(comparisons).getInt("packet") != packet) continue;
      JSONObject expected = golden.getJSONObject(comparisons++);
      assertEquals(
          "capture " + version + " packet " + packet,
          expected.getString("phase").toUpperCase(Locale.ROOT),
          orientation.calibration().phase().name());
      for (int mode = 0; mode < 3; mode++) {
        JSONObject pose =
            expected.getJSONObject(new String[] {"NINTENDO", "GYROSCOPE", "FUSION"}[mode]);
        Orientation.Snapshot actual = orientation.snapshot(t, mode, now);
        assertEquals(
            "capture " + version + " packet " + packet + " mode " + mode,
            pose.getString("status"),
            actual.status());
        if (!pose.has("q")) {
          assertNull(actual.relative());
          continue;
        }
        double dot = 0;
        for (int j = 0; j < 4; j++)
          dot += pose.getJSONArray("q").getDouble(j) * actual.relative()[j];
        for (int j = 0; j < 4; j++)
          assertEquals(
              "quaternion packet " + packet,
              pose.getJSONArray("q").getDouble(j),
              actual.relative()[j] * (dot < 0 ? -1 : 1),
              1e-9);
        double[] angles = Orientation.angles(actual.relative());
        assertEquals("pitch packet " + packet, pose.getDouble("pitch"), angles[0], 1e-7);
        assertEquals("roll packet " + packet, pose.getDouble("roll"), angles[1], 1e-7);
        if (mode == Orientation.FUSION && expected.has("linear_g"))
          assertEquals(
              "linear G packet " + packet,
              expected.getDouble("linear_g"),
              Orientation.norm(actual.linearAcceleration()) / 9.81,
              1e-9);
      }
    }
    JSONObject counts = manifest.getJSONObject("expectations").getJSONObject(version);
    assertEquals(counts.getInt("packets"), lines.size() - 1);
    assertEquals(counts.getInt("subsamples"), samples);
    assertEquals(golden.length(), comparisons);
    System.out.println(
        "Swift 122 parity capture "
            + version
            + ": "
            + (lines.size() - 1)
            + " packets / "
            + samples
            + " subsamples / "
            + comparisons
            + " target snapshots passed");
  }

  @Test
  public void original117CaptureMatchesSwift122() throws Exception {
    replay("117");
  }

  @Test
  public void original118CaptureMatchesSwift122() throws Exception {
    replay("118");
  }

  @Test
  public void physical122CaptureMatchesSwift122Restart() throws Exception {
    replay("122");
  }
}
